// Collect all videos from search results
const allVideos = [];
const seenIds = new Set();

for (const item of $input.all()) {
  const items = item.json.items || [];
  for (const video of items) {
    const videoId = video.id?.videoId;
    if (videoId && !seenIds.has(videoId)) {
      seenIds.add(videoId);
      allVideos.push({
        videoId,
        title: video.snippet?.title || '',
        channelId: video.snippet?.channelId || '',
        channelTitle: video.snippet?.channelTitle || '',
        publishedAt: video.snippet?.publishedAt || '',
        thumbnail: video.snippet?.thumbnails?.high?.url || video.snippet?.thumbnails?.default?.url || '',
        description: (video.snippet?.description || '').substring(0, 200)
      });
    }
  }
}

// Batch video IDs for stats lookup (max 50 per request)
const batches = [];
for (let i = 0; i < allVideos.length; i += 50) {
  batches.push({
    videoIds: allVideos.slice(i, i + 50).map(v => v.videoId).join(','),
    videos: allVideos.slice(i, i + 50)
  });
}

return batches.map(batch => ({ json: batch }));

// Merge video stats with video info
const videosWithStats = [];

for (const item of $input.all()) {
  const statsItems = item.json.items || [];
  const originalVideos = $('Collect Unique Videos').item(item.index).json.videos || [];

  const statsMap = {};
  for (const stat of statsItems) {
    statsMap[stat.id] = {
      viewCount: parseInt(stat.statistics?.viewCount || '0'),
      likeCount: parseInt(stat.statistics?.likeCount || '0'),
      commentCount: parseInt(stat.statistics?.commentCount || '0'),
      duration: stat.contentDetails?.duration || ''
    };
  }

  for (const video of originalVideos) {
    const stats = statsMap[video.videoId];
    if (stats) {
      videosWithStats.push({
        ...video,
        ...stats
      });
    }
  }
}

// Get unique channel IDs
const channelIds = [...new Set(videosWithStats.map(v => v.channelId))];

// Batch channel IDs (max 50 per request)
const batches = [];
for (let i = 0; i < channelIds.length; i += 50) {
  batches.push({
    channelIds: channelIds.slice(i, i + 50).join(',')
  });
}

// Store videos for later
$workflow.videosWithStats = videosWithStats;

return batches.map(batch => ({ json: batch }));

// Build channel subscriber map
const subscriberMap = {};

for (const item of $input.all()) {
  const channels = item.json.items || [];
  for (const channel of channels) {
    subscriberMap[channel.id] = parseInt(channel.statistics?.subscriberCount || '0');
  }
}

// Get stored videos and calculate outlier scores
const videosWithStats = $workflow.videosWithStats || [];

const outliers = [];
const MIN_VIEWS = 5000;
const MAX_SUBSCRIBERS = 100000;
const MIN_OUTLIER_SCORE = 5;

for (const video of videosWithStats) {
  const subscribers = subscriberMap[video.channelId] || 0;

  // Apply filters
  if (video.viewCount < MIN_VIEWS) continue;
  if (subscribers > MAX_SUBSCRIBERS) continue;
  if (subscribers === 0) continue;

  const outlierScore = video.viewCount / subscribers;

  if (outlierScore >= MIN_OUTLIER_SCORE) {
    outliers.push({
      ...video,
      subscriberCount: subscribers,
      outlierScore: Math.round(outlierScore * 10) / 10,
      videoUrl: `https://youtube.com/watch?v=${video.videoId}`,
      channelUrl: `https://youtube.com/channel/${video.channelId}`
    });
  }
}

// Sort by outlier score (highest first)
outliers.sort((a, b) => b.outlierScore - a.outlierScore);

// Take top 25
const topOutliers = outliers.slice(0, 25);

return [{ json: { outliers: topOutliers, totalFound: outliers.length } }];

const { outliers, totalFound } = $input.first().json;
const now = new Date();
const dateStr = now.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

if (outliers.length === 0) {
  return [{
    json: {
      subject: `Shred Athletics Weekly Outliers - ${dateStr}`,
      html: `<h1>No Outliers Found This Week</h1><p>Try adjusting the search parameters or check back next week.</p>`
    }
  }];
}

