    <p><strong>Your Weekly Action:</strong> Pick 1-2 videos above and create your own version this week!</p>
    <p>Model the title, thumbnail, and hook - then make it your own.</p>
    <p style="margin-top: 20px; color: #999;">Generated by Shred Athletics YouTube Outlier Finder</p>
  </div>
</body>
</html>
`;

return [{
  json: {
    subject: `Shred Athletics: ${totalFound} Viral Outliers Found - ${dateStr}`,
    html
  }
}];
